ee:message.ee:set-payload:
%dw 2.0
output application/json
var raw = vars.parameters.FILTERS
var lista = raw splitBy ";"
var pares = lista map (item) -> item splitBy ":"
var filtrados = pares filter (kv) -> sizeOf(kv) == 2
var resultado = filtrados reduce (pair, acc = {}) -> acc ++ {
  (pair[0] as String {lowerFirst: true}): pair[1]
}
---
{
  filtros: resultado
}

%dw 2.0 output application/json var pay = payload."0"."payload"
fun obtenerValor(llave) = (vars.timeslot_user filter ($.Llave == llave))[0].Valor default ""
--- { codeResponse: payload."0"."payload".code, responseMessage: payload."0"."payload".message, appointments: payload."0"."payload".agendas map (item) -> { id: item."_id"."\$oid", actionType: item.action_type, address: item.address, tmrSchedules: item.agendas_tmr map (tmr) -> { id: tmr."_id"."\$oid", scheduleStatus: tmr.estado_agenda, creationDate: tmr.fecha_creacion."\$date", scheduleStartDate: tmr.fecha_inicio_agenda default [], etaId: tmr.id_eta default "", requestedByCustomer: tmr.solicitado_cliente, timeSlot: tmr.timeslot, timeSlotUser: obtenerValor((tmr.timeslot) as String), channel: tmr.canal default "", scheduleEndDate: tmr.fecha_fin_agenda, osmId: tmr.id_osm default "", rescheduleReason: tmr.motivo_reagendamiento default "", scheduleOpportunity: tmr.oportunidad_agenda match { case arr is Array -> arr else -> [tmr.oportunidad_agenda] }, createdByUser: tmr.usuario_creador, modifiedByUser: tmr.usuario_modificador }, connectionNumber: item.connection_number, cun: item.cun, customerDocumentNumber: item.customer_document_number, customerDocumentType: item.customer_document_type, duration: item.duration, updateDate: item.fecha_actualizacion."\$date", orderNumber: item.order_number, orderType: item.order_type, originSystem: item.origin_system, serviceType: item.service_type, skill: item.skill, technicianDocumentNumber: item.technician_document_number, technicianDocumentType: item.technician_document_type, technology: item.technology, createdBy: item.usuario_creo, zone: item.zone } }

