%dw 2.0
output application/json

var raw = vars.parameters.FILTERS
var lista = raw splitBy ";"

var pares =
  lista
    filter ($ != "")
    map (item) -> do {
      var parts = item splitBy ":"
      ---
      {
        key: parts[0],
        value: parts[1 to -1] joinBy ":"
      }
    }

var resultado =
  pares reduce (pair, acc = {}) ->
    acc ++ {
      (pair.key as String { lowerFirst: true }): pair.value
    }

---
{
  filtros: resultado
}

%dw 2.0 output application/json
// Salida directa del Scatter-Gather var route0 = payload[0].payload // assurance var route1 = payload[1].payload // franjas var route2 = payload[2].payload // provisioning
// Parámetros de franjas horarias var timeslotParams = (route1.portal_unificado_conf default []) filter $.Nombre == "FRANJA_AGENDA" flatMap $.Parametros
fun obtenerValor(llave) = (timeslotParams filter ($.Llave == llave))[0].Valor default ""
--- { codeResponse: route0.code, responseMessage: "La solicitud fue exitosa", appointments: {
assurance: (route0.orden default []) map (item) -> { id: item."_id"."\$oid", actionType: item.action_type, address: item.address,
tmrSchedules: (item.agendas_tmr default []) map (tmr) -> { id: tmr."_id"."\$oid", scheduleStatus: tmr.estado_agenda, creationDate: tmr.fecha_creacion, scheduleStartDate: tmr.fecha_inicio_agenda default [], etaId: tmr.id_eta default "", requestedByCustomer: tmr.solicitado_cliente, timeSlot: tmr.timeslot, timeSlotUser: obtenerValor(tmr.timeslot), channel: tmr.canal default "", scheduleEndDate: tmr.fecha_fin_agenda, osmId: tmr.id_osm default "", rescheduleReason: tmr.motivo_reagendamiento default "", scheduleOpportunity: tmr.oportunidad_agenda match { case arr is Array -> arr else -> [tmr.oportunidad_agenda] }, createdByUser: tmr.usuario_creador, modifiedByUser: tmr.usuario_modificador },
connectionNumber: item.connection_number, cun: item.cun, customerDocumentNumber: item.customer_document_number, customerDocumentType: item.customer_document_type, duration: item.duration, updateDate: item.fecha_actualizacion, orderNumber: item.order_number, orderType: item.order_type, originSystem: item.origin_system, serviceType: item.service_type, skill: item.skill, technicianDocumentNumber: item.technician_document_number, technicianDocumentType: item.technician_document_type, technology: item.technology, createdBy: item.usuario_creo, zone: item.zone },
provisioning: (route2 default []) map (prov) -> { scheduling: { scheduledDate: prov.Fecha_Agenda, timeSlot: prov.Franja_Agenda, timeSlotUser: obtenerValor(prov.Franja_Agenda), workType: prov.Tipo_Actuacion default null, workSkill: prov.Habilidad_Trabajo default null, durationMinutes: prov.Duracion default null, installerCode: prov.Codigo_Instalador default "", isEnriched: prov.Enriquecida default false, isScheduled: prov.Agenda default false, activityId: prov.IdActividad, installmentList: prov.ListaCuotas default [] } } } }

