%dw 2.0 output application/json
var request = vars.payloadRequest default {} var order = vars.orderSchedule default {}
// 1. MAPEO ACTIVITY TYPE
var activityTypeMap = { Aprovisionamiento: "INS", Aseguramiento: "AS", Agenda: "INS", Reagenda: "MOD", Cancelacion: "RET", Suspension: "DES" }
var activityType = activityTypeMap[request.scheduleData.visitType] default request.scheduleData.visitType
// 2. MAPEO TECNOLOGÍA
var techMap = { FTTH: "F.O.", COBRE: "CU", FWA: "FWA" }
var techPrefix = techMap[request.scheduleData.technology] default "GEN"
// 3. OBTENER Y LIMPIAR FAMILIAS
var familiasRaw = request.orderData.services map (s) -> s.family
var familiasClean = (familiasRaw filter ($ != null)) distinctBy $
// 4. CONSTRUIR ACTION TYPE
var actionType = techPrefix ++ " (" ++ (familiasClean joinBy "/") ++ ")"
// 5. CALCULAR WORKSKILL
var workSkill = if (techPrefix == "F.O.") "INST_FO" else if (techPrefix == "CU") "INST_CU" else if (techPrefix == "FWA") "INST_FWA" else "GENERIC"
//aun no se ha mapeado actionType
//"aworktype": actionType
---
{ "id_tarea_remedy": request.orderData.orderId, "cedula": order.Cliente_Tramite.Numero_Identificacion, "tipo_actividad": activityType, "franja": request.scheduleData.timeSlot, "nombre_cliente": request.customerData.name, "direccion": request.customerData.address, "ciudad": request.customerData.city, "departamento": request.customerData.state, "zip": null, "cord_x": request.scheduleData.longitude, "cord_y": request.scheduleData.latitude, "telefono": request.customerData.phone, "email": request.customerData.email, "telefono": request.customerData.phone, "XA_request_type": "inmediata", "fecha_agendamiento": request.scheduleData.date, "zona": request.scheduleData.resourceId, "nombre_orden": workSkill, "tipo_actividad": activityType, "cord_x": request.scheduleData.longitude, "cord_y": request.scheduleData.latitude, "Anillo": "", "nemonico_equipo": "", "cable": "", "hilo": "", "distancia": "", "direccion": request.customerData.address, "topologia": "", "zona_agenda": request.scheduleData.zone }
